    ('ec467df8-81ae-576c-90bd-343247eb092b'::uuid, 'Quiz — Quarante ans de paix armée', 'Histoire-Géographie', 'Tle', 'La guerre froide : affrontements et crises politiques dans un monde bipolaire', '2a630129-fce2-5e56-b6f3-05b5ffaca2a2'::uuid),
