    ('ed86bc7b-314d-5e00-978c-87ae67282dff'::uuid, '5e5c0a23-1705-5869-9ded-5a67f3b624d0'::uuid, 'Quelle rafle de juillet 1942 est exécutée par la police française ?', 'mcq', '["La rafle du Vél d’Hiv","La rafle de Marseille","La rafle du Marais","La rafle de Drancy"]'::jsonb, 0, 'Plus de 13 000 personnes arrêtées, dont plus de 4 000 enfants.', 7),
    ('2c6339b8-98fe-5ef8-b4bf-88616ec3fad2'::uuid, '5e5c0a23-1705-5869-9ded-5a67f3b624d0'::uuid, 'Quelle avancée politique majeure le GPRF accorde-t-il en 1944 ?', 'mcq', '["Le droit de vote aux femmes","La Sécurité sociale","Les congés payés","La retraite par répartition"]'::jsonb, 0, 'Elles voteront pour la première fois en avril 1945.', 8),
    ('62387c6a-1ac0-5187-a431-cb8e175a01a1'::uuid, '1f120cc9-d7a0-5e31-a759-2a89f9ce8366'::uuid, 'Combien de Juifs européens sont assassinés pendant la Shoah ?', 'mcq', '["Environ 6 millions","Environ 1 million","Environ 3 millions","Environ 10 millions"]'::jsonb, 0, 'Soit environ les deux tiers des Juifs d’Europe.', 1),
    ('b2742ea6-6e8b-56a8-b0af-23c3a9d4cab0'::uuid, '1f120cc9-d7a0-5e31-a759-2a89f9ce8366'::uuid, 'Que sont les Einsatzgruppen ?', 'mcq', '["Des unités mobiles chargées des fusillades de masse à l’Est","Des camps de travail","Des tribunaux militaires","Des unités de propagande"]'::jsonb, 0, 'Ils opèrent à partir de l’invasion de l’URSS en 1941.', 2),
    ('0b2352ab-97ef-5fc4-8dd5-341074ecfef5'::uuid, '1f120cc9-d7a0-5e31-a759-2a89f9ce8366'::uuid, 'Qu’est-ce que la conférence de Wannsee de janvier 1942 ?', 'mcq', '["Une réunion d’organisation de la « solution finale »","Une conférence de paix","Un sommet allié","Une conférence économique"]'::jsonb, 0, 'Elle coordonne administrativement l’extermination.', 3),
    ('3f9c2209-81c0-533e-89c6-d5dee071964a'::uuid, '1f120cc9-d7a0-5e31-a759-2a89f9ce8366'::uuid, 'Quel est le plus grand centre de mise à mort nazi ?', 'mcq', '["Auschwitz-Birkenau","Dachau","Buchenwald","Bergen-Belsen"]'::jsonb, 0, 'Il combine camp de concentration, de travail et d’extermination.', 4),
    ('971fbf4c-a693-5c01-b92b-a2da31d8384a'::uuid, '1f120cc9-d7a0-5e31-a759-2a89f9ce8366'::uuid, 'Quelle notion juridique naît au procès de Nuremberg ?', 'mcq', '["Le crime contre l’humanité","Le crime de guerre","La légitime défense","Le droit d’asile"]'::jsonb, 0, 'Avec le crime contre la paix : deux catégories nouvelles.', 5),
