    ('2d941e35-7935-5b28-b223-122c259dcf9a'::uuid, '3109def9-5d4f-5b22-afb3-84a4de5a65f5'::uuid, 'Qu’est-ce que l’OAS ?', 'mcq', '["Une organisation clandestine opposée à l’indépendance algérienne","Un parti gaulliste","Un mouvement syndical","Une agence de l’ONU"]'::jsonb, 0, 'Elle mène attentats et tentative de putsch.', 3),
    ('f4cf3f25-3b12-5095-8c1f-4aa358f2673e'::uuid, '3109def9-5d4f-5b22-afb3-84a4de5a65f5'::uuid, 'Quelle décision militaire de 1966 marque l’indépendance française ?', 'mcq', '["Le retrait du commandement intégré de l’OTAN","L’entrée dans le pacte de Varsovie","La création de l’armée européenne","La fin du service militaire"]'::jsonb, 0, 'La France garde l’alliance mais refuse la subordination.', 4),
